INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '123', 4, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT2","type":"lemma","title":"One-sided bound for the Taylor coefficients","statement_tex":"Let $\\psi$ be a primitive character and $0 < \\theta < 1$. Suppose that for every $Y_0 \\ge 1$ there is $Y \\ge Y_0$ with\n\\[ \\mathcal G_\\psi(x) \\le x^\\theta \\qquad \\text{for all } x \\in [Y, Y^{3/2}]. \\]\nFor $k \\ge 0$ and $\\Re s > 1$ let $A_k(s) = \\frac{(-1)^k}{k!}\\,\\mathcal H_\\psi^{(k)}(s)$. Then there is $\\sigma_0 > 2$ such that for every real $\\sigma \\ge \\sigma_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with\n\\[ \\text{for all } k \\in K \\text{ and all } \\tau \\in \\R: \\qquad |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\,(\\sigma - \\theta)^{-k}. \\]","section_id":104,"position":8,"listed":1,"aliases":["one-sided-taylor-bound"]}', 'claude');
UPDATE proofs SET body_tex = 'Put $g(u) = \mathcal G_\psi(e^u)$, a real function, and $g_+ = \max(g, 0)$. Let $\sigma_0 = 200$, as in the \hyperref[8JT4]{concentration of the kernel}, and fix a real $\sigma \ge \sigma_0$. For each $Y \ge 2$ given by the hypothesis put $U = \log Y$ and
\[ W = [U, \tfrac32 U], \qquad k = \bigl\lceil \tfrac54 \sigma U \bigr\rceil, \qquad K_k(u) = \frac{u^k e^{-\sigma u}}{k!}. \]
Here $W$ is the window $Y \le x \le Y^{3/2}$ in the variable $u = \log x$, and $k$ puts the peak $u = k/\sigma$ of $K_k$ (see the \hyperref[8JT6]{graphs of $K_k$}) at the midpoint $\frac54 U$ of $W$, up to rounding. As $k$ grows, almost all of the kernel lies in $W$ (see \hyperref[8JT7]{how $K_k$ concentrates in $W$}). Then for every $\tau \in \R$
\begin{alignat*}{2}
|A_k(\sigma + i\tau)| + \Re A_k(\sigma) &\le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k &\qquad& \text{(a)} \\
&\le 2\int_W e^{\theta u} K_k + 2C_\psi \int_{u \notin W} e^{2u} K_k && \text{(b)} \\
&\le 2(\sigma - \theta)^{-k-1} + 4 C_\psi\, \sigma^{-k} && \text{(c)} \\
&\le (2 + 4C_\psi)\, (\sigma - \theta)^{-k}, && \text{(d)}
\end{alignat*}
where:
\begin{itemize}
\item[(a)] \hyperref[8JT3]{$A_k(\sigma + i\tau) = \int_0^\infty g\, K_k\, e^{-i\tau u}\,du$}, with $K_k \ge 0$ and $|e^{-i\tau u}| = 1$;
\item[(b)] $g_+ \le e^{\theta u}$ on $W$ by the hypothesis, and $g_+ \le C_\psi e^{2u}$ everywhere by \ref{8JS3};
\item[(c)] the \hyperref[8JT4]{concentration of the kernel};
\item[(d)] $\sigma \ge \sigma - \theta \ge 1$.
\end{itemize}
Each such $Y$ gives one $k$, and these $Y$ are unbounded, so the set $K$ of these $k$ is infinite. This proves the claim with $C = 2 + 4C_\psi$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 01:30:00', updated_by = 'claude' WHERE id = 109;
