UPDATE results SET statement_tex = 'For real $\sigma > 2$ and integers $k \ge 0$ let $K_k(u) = u^k e^{-\sigma u}/k!$ for $u \ge 0$.
\begin{enumerate}
\item[(i)] For every real $a < \sigma$, $\displaystyle\int_0^\infty e^{au} K_k(u)\,du = (\sigma - a)^{-k-1}$.
\item[(ii)] Let $\sigma \ge 200$ and $U > 0$, and put $W = [U, \frac32 U]$ and $k = \lceil \frac54 \sigma U \rceil$. Then
\[ \int_{u \notin W} e^{2u} K_k(u)\,du \le 2\sigma^{-k}. \]
\end{enumerate}
See the \hyperref[8JT6]{graphs of $K_k$} and \hyperref[8JT7]{how $K_k$ concentrates in $W$}.', statement_html_cache = NULL, position = 14, visibility = 'published', revision = revision + 1, updated_at = '2026-11-25 01:30:00', updated_by = 'claude' WHERE id = 125;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '125', 2, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT4","type":"lemma","title":"Concentration of the kernel","statement_tex":"For real $\\sigma > 2$ and integers $k \\ge 0$ let $K_k(u) = u^k e^{-\\sigma u}/k!$ for $u \\ge 0$.\n\\begin{enumerate}\n\\item[(i)] For every real $a < \\sigma$, $\\displaystyle\\int_0^\\infty e^{au} K_k(u)\\,du = (\\sigma - a)^{-k-1}$.\n\\item[(ii)] Let $\\sigma \\ge 200$ and $U > 0$, and put $W = [U, \\frac32 U]$ and $k = \\lceil \\frac54 \\sigma U \\rceil$. Then\n\\[ \\int_{u \\notin W} e^{2u} K_k(u)\\,du \\le 2\\sigma^{-k}. \\]\n\\end{enumerate}\nSee the \\hyperref[8JT6]{graphs of $K_k$} and \\hyperref[8JT7]{how $K_k$ concentrates in $W$}.","section_id":104,"position":14,"listed":0,"aliases":["kernel-concentration"]}', 'claude');
UPDATE proofs SET body_tex = '\emph{(i)} \textbf{This is a Gamma integral.} Substitute $v = (\sigma - a)u$ in $\int_0^\infty u^k e^{-(\sigma - a)u}\,du$ and use $\int_0^\infty v^k e^{-v}\,dv = k!$.

\emph{(ii)} \textbf{Outside $W$, bound $1$ by an exponential and integrate over all $u$ with (i).} Put $t = \sigma/5$. We use $\frac54 \sigma U \le k < \frac54 \sigma U + 1$ and, since $\sigma \ge 200$,
\[ \frac45 - \frac2\sigma \ge 0.79 > e^{-6/25} \approx 0.787, \qquad \frac65 - \frac2\sigma \ge 1.19 > e^{4/25} \approx 1.174. \]

\emph{Right of $W$.} For $u > \frac32 U$ we have $1 \le e^{t(u - 3U/2)}$. Hence, by (i) with $a = 2 + t < \sigma$,
\begin{align*}
\int_{u > 3U/2} e^{2u} K_k(u)\,du &\le e^{-3tU/2} \int_0^\infty e^{(2+t)u} K_k(u)\,du \\
&= e^{-3\sigma U/10} \Bigl(\frac45 \sigma - 2\Bigr)^{-k-1} \\
&\le e^{6/25}\, e^{-6k/25}\, \sigma^{-k-1} \Bigl(\frac45 - \frac2\sigma\Bigr)^{-k-1} \\
&= \sigma^{-k} \cdot \frac{e^{6/25}}{\frac45 \sigma - 2} \cdot \biggl(\frac{e^{-6/25}}{\frac45 - \frac2\sigma}\biggr)^{k}.
\end{align*}
The third line uses $\frac{3}{10}\sigma U > \frac{6}{25}(k - 1)$. In the last line the middle factor is less than $1$ and the last factor is at most $1$, so the integral is at most $\sigma^{-k}$.

\emph{Left of $W$.} For $u < U$ we have $1 \le e^{t(U - u)}$. Hence, by (i) with $a = 2 - t$,
\begin{align*}
\int_{u < U} e^{2u} K_k(u)\,du &\le e^{tU} \int_0^\infty e^{(2-t)u} K_k(u)\,du \\
&= e^{\sigma U/5} \Bigl(\frac65 \sigma - 2\Bigr)^{-k-1} \\
&\le \sigma^{-k} \cdot \frac{1}{\frac65 \sigma - 2} \cdot \biggl(\frac{e^{4/25}}{\frac65 - \frac2\sigma}\biggr)^{k},
\end{align*}
using $\frac15 \sigma U \le \frac{4}{25} k$. Again both factors after $\sigma^{-k}$ are at most $1$.

Adding the two bounds gives (ii).', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 01:30:00', updated_by = 'claude' WHERE id = 111;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '111', 3, 'parallel-lemmas-8JP5-2026-11-25', '{"result_id":125,"body_tex":"\\emph{(i)} \\textbf{This is a Gamma integral.} Substitute $v = (\\sigma - a)u$ in $\\int_0^\\infty u^k e^{-(\\sigma - a)u}\\,du$ and use $\\int_0^\\infty v^k e^{-v}\\,dv = k!$.\n\n\\emph{(ii)} \\textbf{Outside $W$, bound $1$ by an exponential and integrate over all $u$ with (i).} Put $t = \\sigma/5$. We use $\\frac54 \\sigma U \\le k < \\frac54 \\sigma U + 1$ and, since $\\sigma \\ge 200$,\n\\[ \\frac45 - \\frac2\\sigma \\ge 0.79 > e^{-6/25} \\approx 0.787, \\qquad \\frac65 - \\frac2\\sigma \\ge 1.19 > e^{4/25} \\approx 1.174. \\]\n\n\\emph{Right of $W$.} For $u > \\frac32 U$ we have $1 \\le e^{t(u - 3U/2)}$. Hence, by (i) with $a = 2 + t < \\sigma$,\n\\begin{align*}\n\\int_{u > 3U/2} e^{2u} K_k(u)\\,du &\\le e^{-3tU/2} \\int_0^\\infty e^{(2+t)u} K_k(u)\\,du \\\\\n&= e^{-3\\sigma U/10} \\Bigl(\\frac45 \\sigma - 2\\Bigr)^{-k-1} \\\\\n&\\le e^{6/25}\\, e^{-6k/25}\\, \\sigma^{-k-1} \\Bigl(\\frac45 - \\frac2\\sigma\\Bigr)^{-k-1} \\\\\n&= \\sigma^{-k} \\cdot \\frac{e^{6/25}}{\\frac45 \\sigma - 2} \\cdot \\biggl(\\frac{e^{-6/25}}{\\frac45 - \\frac2\\sigma}\\biggr)^{k}.\n\\end{align*}\nThe third line uses $\\frac{3}{10}\\sigma U > \\frac{6}{25}(k - 1)$. In the last line the middle factor is less than $1$ and the last factor is at most $1$, so the integral is at most $\\sigma^{-k}$.\n\n\\emph{Left of $W$.} For $u < U$ we have $1 \\le e^{t(U - u)}$. Hence, by (i) with $a = 2 - t$,\n\\begin{align*}\n\\int_{u < U} e^{2u} K_k(u)\\,du &\\le e^{tU} \\int_0^\\infty e^{(2-t)u} K_k(u)\\,du \\\\\n&= e^{\\sigma U/5} \\Bigl(\\frac65 \\sigma - 2\\Bigr)^{-k-1} \\\\\n&\\le \\sigma^{-k} \\cdot \\frac{1}{\\frac65 \\sigma - 2} \\cdot \\biggl(\\frac{e^{4/25}}{\\frac65 - \\frac2\\sigma}\\biggr)^{k},\n\\end{align*}\nusing $\\frac15 \\sigma U \\le \\frac{4}{25} k$. Again both factors after $\\sigma^{-k}$ are at most $1$.\n\nAdding the two bounds gives (ii).","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
