UPDATE proofs SET body_tex = '\emph{Idea.} The numbers $A_k(z) = \frac{(-1)^k}{k!}\mathcal H_\psi^{(k)}(z)$ are the Taylor coefficients of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, they grow like $d^{-k}$. Two parallel lemmas compare this growth on the line $\Re z = \sigma$ with $(\sigma - \theta)^{-k}$:
\begin{itemize}
\item the hypothesis caps it, by the \hyperref[8JT2]{one-sided bound for the Taylor coefficients};
\item a pole with $\Re\rho > \theta$ would exceed the cap, by the \hyperref[8JT5]{lower bound for the Taylor coefficients}.
\end{itemize}
Both lemmas bound the same quantity $|A_k(\sigma + i\tau)| + \Re A_k(\sigma)$, one from above and one from below. The upper bound works for this combination because it is at most $2\int_0^\infty g_+ K_k$, with $g(u) = \mathcal G_\psi(e^u)$, which involves only the positive part of $\mathcal G_\psi$: the hypothesis bounds $\mathcal G_\psi$ only from above.

\emph{The contradiction.} Suppose that some $\rho \in Z$ has $\Re\rho > \theta$. The hypothesis of the proposition is that of \ref{8JT2}; let $\sigma_0$ be as there, fix a real $\sigma \ge \sigma_0$, and let $C$ and $K$ be as there. Since $\sigma > 1$, \ref{8JT5} gives $\tau$, $c$, $d < \sigma - \theta$ and $k_0$. For every $k \in K$ with $k \ge k_0$,
\[ c\, d^{-k} \le |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\, (\sigma - \theta)^{-k}, \qquad \text{so} \qquad \Bigl(\frac{\sigma - \theta}{d}\Bigr)^{k} \le \frac Cc. \]
Since $K$ is infinite and $(\sigma - \theta)/d > 1$, this fails for large $k \in K$. Hence $\Re\rho \le \theta$ for every $\rho \in Z$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 01:30:00', updated_by = 'claude' WHERE id = 102;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '102', 9, 'parallel-lemmas-8JP5-2026-11-25', '{"result_id":113,"body_tex":"\\emph{Idea.} The numbers $A_k(z) = \\frac{(-1)^k}{k!}\\mathcal H_\\psi^{(k)}(z)$ are the Taylor coefficients of $w \\mapsto \\mathcal H_\\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, they grow like $d^{-k}$. Two parallel lemmas compare this growth on the line $\\Re z = \\sigma$ with $(\\sigma - \\theta)^{-k}$:\n\\begin{itemize}\n\\item the hypothesis caps it, by the \\hyperref[8JT2]{one-sided bound for the Taylor coefficients};\n\\item a pole with $\\Re\\rho > \\theta$ would exceed the cap, by the \\hyperref[8JT5]{lower bound for the Taylor coefficients}.\n\\end{itemize}\nBoth lemmas bound the same quantity $|A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma)$, one from above and one from below. The upper bound works for this combination because it is at most $2\\int_0^\\infty g_+ K_k$, with $g(u) = \\mathcal G_\\psi(e^u)$, which involves only the positive part of $\\mathcal G_\\psi$: the hypothesis bounds $\\mathcal G_\\psi$ only from above.\n\n\\emph{The contradiction.} Suppose that some $\\rho \\in Z$ has $\\Re\\rho > \\theta$. The hypothesis of the proposition is that of \\ref{8JT2}; let $\\sigma_0$ be as there, fix a real $\\sigma \\ge \\sigma_0$, and let $C$ and $K$ be as there. Since $\\sigma > 1$, \\ref{8JT5} gives $\\tau$, $c$, $d < \\sigma - \\theta$ and $k_0$. For every $k \\in K$ with $k \\ge k_0$,\n\\[ c\\, d^{-k} \\le |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\, (\\sigma - \\theta)^{-k}, \\qquad \\text{so} \\qquad \\Bigl(\\frac{\\sigma - \\theta}{d}\\Bigr)^{k} \\le \\frac Cc. \\]\nSince $K$ is infinite and $(\\sigma - \\theta)/d > 1$, this fails for large $k \\in K$. Hence $\\Re\\rho \\le \\theta$ for every $\\rho \\in Z$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
