INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (136, '8JT5', 'lemma', 'Lower bound for the Taylor coefficients when a pole has $\Re\rho > \theta$', 'Let $\psi$ be a primitive character and $0 < \theta < 1$. Suppose that some pole $\rho$ of $\mathcal H_\psi$, that is, some $\rho$ in the \hyperref[8JN4]{set of poles} $Z$, satisfies $\Re\rho > \theta$. For $k \ge 0$ and $\Re s > 1$ let $A_k(s) = \frac{(-1)^k}{k!}\,\mathcal H_\psi^{(k)}(s)$. Then for every real $\sigma > 1$ there are $\tau \in \R$, $c > 0$, $0 < d < \sigma - \theta$ and $k_0 \ge 0$ with
\[ \text{for all } k \ge k_0: \qquad |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \ge c\, d^{-k}. \]', NULL, 104, 9, 'published', 1, 1, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '136', 1, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT5","type":"lemma","title":"Lower bound for the Taylor coefficients when a pole has $\\Re\\rho > \\theta$","statement_tex":"Let $\\psi$ be a primitive character and $0 < \\theta < 1$. Suppose that some pole $\\rho$ of $\\mathcal H_\\psi$, that is, some $\\rho$ in the \\hyperref[8JN4]{set of poles} $Z$, satisfies $\\Re\\rho > \\theta$. For $k \\ge 0$ and $\\Re s > 1$ let $A_k(s) = \\frac{(-1)^k}{k!}\\,\\mathcal H_\\psi^{(k)}(s)$. Then for every real $\\sigma > 1$ there are $\\tau \\in \\R$, $c > 0$, $0 < d < \\sigma - \\theta$ and $k_0 \\ge 0$ with\n\\[ \\text{for all } k \\ge k_0: \\qquad |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\ge c\\, d^{-k}. \\]","section_id":104,"position":9,"listed":1,"aliases":["taylor-lower-bound"]}', 'claude');
