INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (121, 136, 1, '\emph{Idea.} $A_k(z)$ is the $k$-th Taylor coefficient of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, then $|A_k(z)|$ grows like $d^{-k}$ (Step 1). A pole with $\Re\rho > \theta$ is closer than $\sigma - \theta$ to the line $\Re s = \sigma$; we find a point of that line where it shows up in $A_k$.

\emph{Step 1: Taylor coefficients near a pole.} Let $\Re z > 1$, and let $\overline B(z, r)$ be a closed disc in $\Re s > 0$ that contains exactly one pole $\rho$ of $\mathcal H_\psi$, with residue $c_\rho$. Then
\[ A_k(z) = \frac{c_\rho}{(z - \rho)^{k+1}} + O(r^{-k}) \qquad (k \to \infty). \]
Indeed, write $\mathcal H_\psi(s) = \frac{c_\rho}{s - \rho} + h(s)$ with $h$ holomorphic on a neighbourhood of $\overline B(z, r)$. Since $\frac{d^k}{ds^k}\frac{1}{s - \rho} = \frac{(-1)^k k!}{(s - \rho)^{k+1}}$, the first term contributes $\frac{c_\rho}{(z - \rho)^{k+1}}$ to $A_k(z)$, and Cauchy''s estimate gives $\frac{|h^{(k)}(z)|}{k!} \le r^{-k} \max_{|s - z| = r} |h(s)|$. In the same way $A_k(z) = O(r^{-k})$ if $\overline B(z, r)$ contains no pole.

\emph{Step 2: two distances.} Fix $\sigma > 1$, and put $D_* = \sigma - \theta$ and $D = \min_{\rho \in Z} |\sigma - \rho|$, the distance from $\sigma$ to the nearest pole; the minimum exists because $Z$ is nonempty and \hyperref[8JS5]{locally finite}. Every pole is \hyperref[8JN4]{simple with nonzero residue}, and every pole has $\Re\rho < 1 < \sigma$, since $L(s,\chi) \ne 0$ for $\Re s \ge 1$ \cite{Davenport}. By hypothesis some $\rho_0 \in Z$ has $\sigma - \Re\rho_0 < D_*$. All discs below are centred on the line $\Re s = \sigma$ and have radius less than $D_* < \sigma$, so they lie in $\Re s > 0$.

\emph{Case (a): some pole $\rho_1$ has $\sigma - \Re\rho_1 < \min(D, D_*)$.} Choose a closed interval $J$ around $\Im\rho_1$ such that $|\sigma + i\tau - \rho_1| < \min(D, D_*)$ for all $\tau \in J$. Only finitely many poles lie within distance $\min(D, D_*)$ of the compact segment $\{\sigma + i\tau \mid \tau \in J\}$. Two of them are equidistant from $\sigma + i\tau$ for at most one $\tau$: if their imaginary parts differ, equality of the squared distances is a linear equation in $\tau$ with nonzero slope; if their imaginary parts agree, their real parts differ, and since both lie left of the line their distances to it differ. Choose $\tau \in J$ avoiding these finitely many values and put $z = \sigma + i\tau$. Then $z$ has a unique nearest pole $\rho$, at distance $d \le |z - \rho_1| < \min(D, D_*)$. Choose $r$ with $d < r < \min(D, D_*)$ such that $\rho$ is the only pole in $\overline B(z, r)$. The disc $\overline B(\sigma, r)$ contains no pole, as $r < D$. By Step 1,
\[ |A_k(z)| + \Re A_k(\sigma) \ge |A_k(z)| - |A_k(\sigma)| \ge |c_\rho|\, d^{-k-1} - O(r^{-k}) \ge \frac{|c_\rho|}{2d}\, d^{-k} \]
for all large $k$, because $d < r$. This is the claim with $c = |c_\rho|/(2d)$. We cannot simply take $z = \sigma$: there the conjugate poles $\rho_1$ and $\bar\rho_1$ are equally close, and their contributions to $A_k(\sigma)$ may cancel. See the \hyperref[8JT8]{picture of case (a)}.

\emph{Case (b): every pole has $\sigma - \Re\rho \ge \min(D, D_*)$.} For $\rho_0$ this gives $\min(D, D_*) \le \sigma - \Re\rho_0 < D_*$, so $D < D_*$. A pole $\rho$ nearest to $\sigma$ satisfies $D = |\sigma - \rho| \ge \sigma - \Re\rho \ge D$. So equality holds, $\rho$ is real, and $\rho = \beta = \sigma - D$; in particular $\beta$ is the only pole at distance $D$ from $\sigma$. Its residue $c_\beta$ is positive by the \hyperref[8JS7]{corollary on real poles}. Choose $r$ with $D < r < D_*$ such that $\beta$ is the only pole in $\overline B(\sigma, r)$. By Step 1, $A_k(\sigma) = c_\beta D^{-k-1} + O(r^{-k})$, so with $\tau = 0$
\[ |A_k(\sigma)| + \Re A_k(\sigma) \ge 2\Re A_k(\sigma) \ge 2c_\beta D^{-k-1} - O(r^{-k}) \ge \frac{c_\beta}{D}\, D^{-k} \]
for all large $k$. This is the claim with $d = D$ and $c = c_\beta/D$. Here the sign of $c_\beta$ is essential: if $c_\beta$ were negative, $|A_k(\sigma)| + \Re A_k(\sigma)$ could be small. See the \hyperref[8JT9]{picture of case (b)}.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '121', 1, 'parallel-lemmas-8JP5-2026-11-25', '{"result_id":136,"body_tex":"\\emph{Idea.} $A_k(z)$ is the $k$-th Taylor coefficient of $w \\mapsto \\mathcal H_\\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, then $|A_k(z)|$ grows like $d^{-k}$ (Step 1). A pole with $\\Re\\rho > \\theta$ is closer than $\\sigma - \\theta$ to the line $\\Re s = \\sigma$; we find a point of that line where it shows up in $A_k$.\n\n\\emph{Step 1: Taylor coefficients near a pole.} Let $\\Re z > 1$, and let $\\overline B(z, r)$ be a closed disc in $\\Re s > 0$ that contains exactly one pole $\\rho$ of $\\mathcal H_\\psi$, with residue $c_\\rho$. Then\n\\[ A_k(z) = \\frac{c_\\rho}{(z - \\rho)^{k+1}} + O(r^{-k}) \\qquad (k \\to \\infty). \\]\nIndeed, write $\\mathcal H_\\psi(s) = \\frac{c_\\rho}{s - \\rho} + h(s)$ with $h$ holomorphic on a neighbourhood of $\\overline B(z, r)$. Since $\\frac{d^k}{ds^k}\\frac{1}{s - \\rho} = \\frac{(-1)^k k!}{(s - \\rho)^{k+1}}$, the first term contributes $\\frac{c_\\rho}{(z - \\rho)^{k+1}}$ to $A_k(z)$, and Cauchy''s estimate gives $\\frac{|h^{(k)}(z)|}{k!} \\le r^{-k} \\max_{|s - z| = r} |h(s)|$. In the same way $A_k(z) = O(r^{-k})$ if $\\overline B(z, r)$ contains no pole.\n\n\\emph{Step 2: two distances.} Fix $\\sigma > 1$, and put $D_* = \\sigma - \\theta$ and $D = \\min_{\\rho \\in Z} |\\sigma - \\rho|$, the distance from $\\sigma$ to the nearest pole; the minimum exists because $Z$ is nonempty and \\hyperref[8JS5]{locally finite}. Every pole is \\hyperref[8JN4]{simple with nonzero residue}, and every pole has $\\Re\\rho < 1 < \\sigma$, since $L(s,\\chi) \\ne 0$ for $\\Re s \\ge 1$ \\cite{Davenport}. By hypothesis some $\\rho_0 \\in Z$ has $\\sigma - \\Re\\rho_0 < D_*$. All discs below are centred on the line $\\Re s = \\sigma$ and have radius less than $D_* < \\sigma$, so they lie in $\\Re s > 0$.\n\n\\emph{Case (a): some pole $\\rho_1$ has $\\sigma - \\Re\\rho_1 < \\min(D, D_*)$.} Choose a closed interval $J$ around $\\Im\\rho_1$ such that $|\\sigma + i\\tau - \\rho_1| < \\min(D, D_*)$ for all $\\tau \\in J$. Only finitely many poles lie within distance $\\min(D, D_*)$ of the compact segment $\\{\\sigma + i\\tau \\mid \\tau \\in J\\}$. Two of them are equidistant from $\\sigma + i\\tau$ for at most one $\\tau$: if their imaginary parts differ, equality of the squared distances is a linear equation in $\\tau$ with nonzero slope; if their imaginary parts agree, their real parts differ, and since both lie left of the line their distances to it differ. Choose $\\tau \\in J$ avoiding these finitely many values and put $z = \\sigma + i\\tau$. Then $z$ has a unique nearest pole $\\rho$, at distance $d \\le |z - \\rho_1| < \\min(D, D_*)$. Choose $r$ with $d < r < \\min(D, D_*)$ such that $\\rho$ is the only pole in $\\overline B(z, r)$. The disc $\\overline B(\\sigma, r)$ contains no pole, as $r < D$. By Step 1,\n\\[ |A_k(z)| + \\Re A_k(\\sigma) \\ge |A_k(z)| - |A_k(\\sigma)| \\ge |c_\\rho|\\, d^{-k-1} - O(r^{-k}) \\ge \\frac{|c_\\rho|}{2d}\\, d^{-k} \\]\nfor all large $k$, because $d < r$. This is the claim with $c = |c_\\rho|/(2d)$. We cannot simply take $z = \\sigma$: there the conjugate poles $\\rho_1$ and $\\bar\\rho_1$ are equally close, and their contributions to $A_k(\\sigma)$ may cancel. See the \\hyperref[8JT8]{picture of case (a)}.\n\n\\emph{Case (b): every pole has $\\sigma - \\Re\\rho \\ge \\min(D, D_*)$.} For $\\rho_0$ this gives $\\min(D, D_*) \\le \\sigma - \\Re\\rho_0 < D_*$, so $D < D_*$. A pole $\\rho$ nearest to $\\sigma$ satisfies $D = |\\sigma - \\rho| \\ge \\sigma - \\Re\\rho \\ge D$. So equality holds, $\\rho$ is real, and $\\rho = \\beta = \\sigma - D$; in particular $\\beta$ is the only pole at distance $D$ from $\\sigma$. Its residue $c_\\beta$ is positive by the \\hyperref[8JS7]{corollary on real poles}. Choose $r$ with $D < r < D_*$ such that $\\beta$ is the only pole in $\\overline B(\\sigma, r)$. By Step 1, $A_k(\\sigma) = c_\\beta D^{-k-1} + O(r^{-k})$, so with $\\tau = 0$\n\\[ |A_k(\\sigma)| + \\Re A_k(\\sigma) \\ge 2\\Re A_k(\\sigma) \\ge 2c_\\beta D^{-k-1} - O(r^{-k}) \\ge \\frac{c_\\beta}{D}\\, D^{-k} \\]\nfor all large $k$. This is the claim with $d = D$ and $c = c_\\beta/D$. Here the sign of $c_\\beta$ is essential: if $c_\\beta$ were negative, $|A_k(\\sigma)| + \\Re A_k(\\sigma)$ could be small. See the \\hyperref[8JT9]{picture of case (b)}.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
