INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (137, '8JT6', 'example', 'Graphs of the kernels $K_k$', 'For $\sigma > 0$ and $k \ge 1$ let $K_k(u) = u^k e^{-\sigma u}/k!$ for $u \ge 0$, as in the \hyperref[8JT4]{concentration of the kernel}. Since $K_k(0) = 0$ and $\frac{d}{du} \log K_k(u) = \frac ku - \sigma$ for $u > 0$, the kernel increases up to $u = k/\sigma$ and decreases after it. The graphs show $K_1$, $K_2$, $K_3$ for $\sigma = 1$, with dashed lines at the peaks $u = 1, 2, 3$.
\includegraphics[width=1, alt=The kernels K_1, K_2, K_3 for sigma = 1, with dashed lines at their peaks]{/static/figures/gamma-kernel-a.svg}', NULL, 104, 15, 'published', 0, 1, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '137', 1, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT6","type":"example","title":"Graphs of the kernels $K_k$","statement_tex":"For $\\sigma > 0$ and $k \\ge 1$ let $K_k(u) = u^k e^{-\\sigma u}/k!$ for $u \\ge 0$, as in the \\hyperref[8JT4]{concentration of the kernel}. Since $K_k(0) = 0$ and $\\frac{d}{du} \\log K_k(u) = \\frac ku - \\sigma$ for $u > 0$, the kernel increases up to $u = k/\\sigma$ and decreases after it. The graphs show $K_1$, $K_2$, $K_3$ for $\\sigma = 1$, with dashed lines at the peaks $u = 1, 2, 3$.\n\\includegraphics[width=1, alt=The kernels K_1, K_2, K_3 for sigma = 1, with dashed lines at their peaks]{/static/figures/gamma-kernel-a.svg}","section_id":104,"position":15,"listed":0,"aliases":["kernel-graphs"]}', 'claude');
