INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (138, '8JT7', 'example', 'The kernels $K_k$ concentrate in $W$', 'Let $U > 0$ and $W = [U, \frac32 U]$, and let $\sigma > 0$ and a positive integer $k$ satisfy $k/\sigma = \frac54 U$, so that the kernel $K_k(u) = u^k e^{-\sigma u}/k!$ peaks at the midpoint of $W$, as in the \hyperref[8JT2]{one-sided bound} up to rounding. Rescaled to peak value $1$, the kernel is
\[ \frac{K_k(u)}{K_k(k/\sigma)} = \Bigl(\frac{\sigma u}{k}\Bigr)^{k} e^{k - \sigma u}, \]
which depends only on $k$ and $u/U$. The graphs show it for $k = 3, 30, 300$, with $W$ shaded. As $k$ grows, the kernel concentrates in $W$; part (ii) of the \hyperref[8JT4]{concentration of the kernel} is a quantitative version of this.
\includegraphics[width=1, alt=Rescaled kernels for k = 3, 30, 300 peaking at 5U/4, the midpoint of the shaded interval W]{/static/figures/gamma-kernel-b.svg}', NULL, 104, 16, 'published', 0, 1, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '138', 1, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT7","type":"example","title":"The kernels $K_k$ concentrate in $W$","statement_tex":"Let $U > 0$ and $W = [U, \\frac32 U]$, and let $\\sigma > 0$ and a positive integer $k$ satisfy $k/\\sigma = \\frac54 U$, so that the kernel $K_k(u) = u^k e^{-\\sigma u}/k!$ peaks at the midpoint of $W$, as in the \\hyperref[8JT2]{one-sided bound} up to rounding. Rescaled to peak value $1$, the kernel is\n\\[ \\frac{K_k(u)}{K_k(k/\\sigma)} = \\Bigl(\\frac{\\sigma u}{k}\\Bigr)^{k} e^{k - \\sigma u}, \\]\nwhich depends only on $k$ and $u/U$. The graphs show it for $k = 3, 30, 300$, with $W$ shaded. As $k$ grows, the kernel concentrates in $W$; part (ii) of the \\hyperref[8JT4]{concentration of the kernel} is a quantitative version of this.\n\\includegraphics[width=1, alt=Rescaled kernels for k = 3, 30, 300 peaking at 5U/4, the midpoint of the shaded interval W]{/static/figures/gamma-kernel-b.svg}","section_id":104,"position":16,"listed":0,"aliases":["kernel-concentration-graph"]}', 'claude');
