INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (139, '8JT8', 'example', 'Poles in case (a) of the lower bound', 'This picture shows an illustrative configuration for case (a) in the proof of the \hyperref[8JT5]{lower bound for the Taylor coefficients}. The solid line is $\Re s = \sigma$, the dashed line is $\Re s = \theta$, the strip between them is shaded, and $D_* = \sigma - \theta$. Here the poles nearest to $\sigma$ are $\rho_1$ and $\bar\rho_1$ (red), at the same distance $D$ (dashed circle), so their contributions to $A_k(\sigma)$ may cancel. The point $z = \sigma + i\tau$ is closer to $\rho_1$ (blue circle, radius $d$) than $\sigma$ is to any pole, and $\rho_1$ is the only pole at distance $d$ from $z$. The picture is not to scale: in the application to the \hyperref[8JP5]{interval criterion}, $\sigma \ge 200$, and all poles lie in $0 < \Re s < 1$.
\includegraphics[width=0.7, alt=Case a: the line Re s = sigma, the strip Re s greater than theta shaded, a blue circle around z touching the pole rho_1, and a dashed circle around sigma through rho_1 and its conjugate]{/static/figures/interval-criterion-a.svg}', NULL, 104, 17, 'published', 0, 1, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '139', 1, 'parallel-lemmas-8JP5-2026-11-25', '{"tag":"8JT8","type":"example","title":"Poles in case (a) of the lower bound","statement_tex":"This picture shows an illustrative configuration for case (a) in the proof of the \\hyperref[8JT5]{lower bound for the Taylor coefficients}. The solid line is $\\Re s = \\sigma$, the dashed line is $\\Re s = \\theta$, the strip between them is shaded, and $D_* = \\sigma - \\theta$. Here the poles nearest to $\\sigma$ are $\\rho_1$ and $\\bar\\rho_1$ (red), at the same distance $D$ (dashed circle), so their contributions to $A_k(\\sigma)$ may cancel. The point $z = \\sigma + i\\tau$ is closer to $\\rho_1$ (blue circle, radius $d$) than $\\sigma$ is to any pole, and $\\rho_1$ is the only pole at distance $d$ from $z$. The picture is not to scale: in the application to the \\hyperref[8JP5]{interval criterion}, $\\sigma \\ge 200$, and all poles lie in $0 < \\Re s < 1$.\n\\includegraphics[width=0.7, alt=Case a: the line Re s = sigma, the strip Re s greater than theta shaded, a blue circle around z touching the pole rho_1, and a dashed circle around sigma through rho_1 and its conjugate]{/static/figures/interval-criterion-a.svg}","section_id":104,"position":17,"listed":0,"aliases":["interval-criterion-case-a"]}', 'claude');
