INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (140, '8JT9', 'example', 'Poles in case (b) of the lower bound', 'This picture shows an illustrative configuration for case (b) in the proof of the \hyperref[8JT5]{lower bound for the Taylor coefficients}. Here $D$ is the distance from $\sigma$ to the nearest pole (dashed circle), and every pole lies in $\Re s \le \sigma - D$, left of the dotted line. The nearest pole is then the real pole $\beta = \sigma - D$ (red), whose residue is positive. The picture is not to scale: in the application to the \hyperref[8JP5]{interval criterion}, $\sigma \ge 200$, and all poles lie in $0 < \Re s < 1$.
\includegraphics[width=0.7, alt=Case b: the dashed circle around sigma touches the real pole beta, and all poles lie left of the dotted line Re s = sigma minus D]{/static/figures/interval-criterion-b.svg}', NULL, 104, 18, 'published', 0, 1, '2026-11-25 01:30:00', '2026-11-25 01:30:00', 'claude', 'claude');
